begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('34000000-0000-4000-8000-000000000001','archive-a@example.invalid'),('34000000-0000-4000-8000-000000000002','archive-b@example.invalid'),('34000000-0000-4000-8000-000000000003','archive-c@example.invalid');
insert into public.households(id,name) values ('34000000-0000-4000-8000-000000000100','Archive fixture'),('34000000-0000-4000-8000-000000000200','Other archive fixture');
insert into public.household_members(household_id,user_id,display_name) values ('34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000001','Member 1'),('34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000002','Member 2'),('34000000-0000-4000-8000-000000000200','34000000-0000-4000-8000-000000000003','Member 3');
select set_config('request.jwt.claim.sub','34000000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into public.household_decisions(id,household_id,created_by,title) values ('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000001','Travel'),('34000000-0000-4000-8000-000000000011','34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000001','Empty decision');
insert into public.decision_options(id,household_id,created_by,decision_id,title) values ('34000000-0000-4000-8000-000000000020','34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000010','Option 20'),('34000000-0000-4000-8000-000000000021','34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000010','Option 21');
select public.choose_household_decision_option('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000020');
update public.household_decisions set archived_at=now() where id in ('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000011');
select set_config('test.decision.version',(select updated_at::text from public.household_decisions where id='34000000-0000-4000-8000-000000000010'),true);
select set_config('request.jwt.claim.sub','34000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.choose_household_decision_option('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000021')$$,'55000','Restore this decision before changing its choice','partner cannot change an archived choice');
select throws_ok($$select public.choose_household_decision_option('34000000-0000-4000-8000-000000000010',null)$$,'55000','Restore this decision before changing its choice','partner cannot change an archived choice');
select set_config('test.empty.version',(select updated_at::text from public.household_decisions where id='34000000-0000-4000-8000-000000000011'),true);
-- Newer RPCs may return without writing for a true no-op; older RPCs hit the guard.
do $$ begin
  perform public.choose_household_decision_option('34000000-0000-4000-8000-000000000011',null);
exception when sqlstate '55000' then null;
end $$;
select is((select updated_at::text from public.household_decisions where id='34000000-0000-4000-8000-000000000011'),current_setting('test.empty.version'),'clearing an empty archived decision cannot update its version');
select throws_ok($$update public.household_decisions set status='dismissed' where id='34000000-0000-4000-8000-000000000010'$$,'55000','Restore this decision before changing its status','direct status writes respect archive state');
select throws_ok($$update public.household_decisions set archived_at=null, status='dismissed' where id='34000000-0000-4000-8000-000000000010'$$,'55000','Restore this decision before changing its status','status cannot change in the restore statement');
insert into public.household_decisions(id,household_id,created_by,title) values ('34000000-0000-4000-8000-000000000012','34000000-0000-4000-8000-000000000100','34000000-0000-4000-8000-000000000002','Active decision');
select throws_ok($$update public.decision_options set decision_id='34000000-0000-4000-8000-000000000012' where id='34000000-0000-4000-8000-000000000020'$$,'23514','An option belongs to its original decision','a chosen option cannot escape its archived parent');
select is((select chosen from public.decision_options where id='34000000-0000-4000-8000-000000000020'),true,'original choice remains');
select is((select chosen from public.decision_options where id='34000000-0000-4000-8000-000000000021'),false,'alternative remains unchosen');
select is((select status from public.household_decisions where id='34000000-0000-4000-8000-000000000010'),'decided','status is preserved');
select is((select updated_at::text from public.household_decisions where id='34000000-0000-4000-8000-000000000010'),current_setting('test.decision.version'),'rejected choice preserves version');
update public.household_decisions set archived_at=null where id='34000000-0000-4000-8000-000000000010';
select lives_ok($$select public.choose_household_decision_option('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000021')$$,'either member can choose after restoring');
select is((select chosen from public.decision_options where id='34000000-0000-4000-8000-000000000021'),true,'restored decision accepts choice');
select set_config('request.jwt.claim.sub','34000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.choose_household_decision_option('34000000-0000-4000-8000-000000000010','34000000-0000-4000-8000-000000000020')$$,'42501','Decision not found','foreign household remains denied');
select is_empty($$select id from public.decision_options where household_id='34000000-0000-4000-8000-000000000100'$$,'foreign options remain hidden');
select * from finish();
rollback;
